    TRANSLATION_OVERRIDES[_language]['Карты проекта и этапов в облаке'] = _title
    TRANSLATION_OVERRIDES[_language][_MAP_HELP_PARAGRAPHS["ru"]] = _MAP_HELP_PARAGRAPHS[_language]
